tools.example:
p = loadAudioPlugin("C:/VST3/MyReverb.vst3");
dispParameter(p)
setParameter(p, 1, 0.7);
setSampleRate(p, 48000);
y = process(p, x);

fs = 48e3;
[B, A] = designParamEQ(2, 6, 1000/(fs/2), 300/(fs/2), Orientation="row");
sos = [B, A];
y = sosfilt(sos, x);

eq = multibandParametricEQ(NumEQBands=3, Frequencies=[200 1000 5000], ...
    QualityFactors=[1 2 1], PeakGains=[-3 4 2], SampleRate=48000);
y = eq(x);
visualize(eq)

geq = graphicEQ(Bandwidth="1 octave", SampleRate=48000);
geq.Gains = [0 2 4 2 0 -2 -3 0 1 2];
y = geq(x);

cf = crossoverFilter(NumCrossovers=2, CrossoverFrequencies=[250 3000], ...
    CrossoverSlopes=[24 24], SampleRate=48000);
[low, mid, high] = cf(x);

ofb = octaveFilterBank("1/3 octave", 48000, FrequencyRange=[100 8000]);
y = ofb(x);                          % samples-by-bands
fc = getCenterFrequencies(ofb);

gfb = gammatoneFilterBank(FrequencyRange=[50 8000], NumFilters=32, SampleRate=16000);
y = gfb(x);
fc = getCenterFrequencies(gfb);

aw = weightingFilter("A-weighting", 48000);
yA = aw(x);
visualize(aw)

dRC = compressor(Threshold=-20, Ratio=4, KneeWidth=6, AttackTime=0.01, ...
    ReleaseTime=0.2, SampleRate=fs);
[y, g] = dRC(x);
visualize(dRC)

rv = reverberator(PreDelay=0.02, DecayFactor=0.6, WetDryMix=0.3, SampleRate=fs);
y = rv(x);
sound(y, fs)

[x, fs] = audioread("Counting-16-44p1-mono-15secs.wav");
y = shiftPitch(x, 3, PreserveFormants=true);
sound(y, fs)

aug = audioDataAugmenter(NumAugmentations=4, TimeStretchProbability=0.5, ...
    PitchShiftProbability=0.5, SemitoneShiftRange=[-2 2], AddNoiseProbability=0.8, SNRRange=[5 20]);
data = augment(aug, x, fs);
data.Audio{1}

[x, fs] = audioread("Counting-16-44p1-mono-15secs.wav");
idx = detectSpeech(x, fs);
segments = arrayfun(@(k) x(idx(k,1):idx(k,2)), 1:size(idx,1), UniformOutput=false);

[net, classNames] = audioPretrainedNetwork("yamnet");
feats = yamnetPreprocess(x, fs);
scores = predict(net, feats);
[~, k] = max(mean(scores, 1));
classNames(k)

[x, fs] = audioread("speech_dft.wav");
client = speechClient("wav2vec2.0");
txt = speech2text(x, fs, Client=client)

ivs = ivectorSystem(SampleRate=16000);
trainExtractor(ivs, adsTrain, UBMNumComponents=64, TVSRank=32);
trainClassifier(ivs, adsTrain, adsTrain.Labels);
enroll(ivs, adsEnroll, adsEnroll.Labels);
identify(ivs, testAudio)

c = mfcc(x, fs);
d = audioDelta(c);
dd = audioDelta(d);

[x, fs] = audioread("RockDrums-48-stereo-11secs.mp3");
[L, LRA] = integratedLoudness(x, fs)
gain = 10^((-23 - L)/20);    % normalize to -23 LUFS
y = gain * x;

lm = loudnessMeter(SampleRate=fs);
[m, s, i, lra, tp] = lm(x);
visualize(lm)

cal = calibrateMicrophone(calTone, fs, 94);   % 94 dB SPL calibrator
spl = splMeter(CalibrationFactor=cal, SampleRate=fs);
[LT, Leq] = spl(measurement);

fs = 48000;
exc = sweeptone(3, 1, fs);
h = [1 zeros(1,99) 0.5 zeros(1,199) 0.25]';    % simulated system
rec = filter(h, 1, exc);                       % or record with audioPlayerRecorder
ir = impzest(exc, rec);
plot((0:numel(ir)-1)/fs, ir)

s = sofaread("ReferenceHRTF.sofa");
size(s.Numerator)          % measurements-by-receivers-by-samples (FIR conventions)
hrtf = interpolateHRTF(s.Numerator, s.SourcePosition(:,1:2), [30 0]);
